import sys, os
sys.path.insert(0, os.path.join('.codex', 'skills', 'docx'))
from scripts.document import Document

doc = Document('unpacked')
editor = doc["word/document.xml"]
body = editor.dom.getElementsByTagName('w:body')[0]

def para_text(p):
    parts = []
    for node in p.childNodes:
        if node.nodeType == node.ELEMENT_NODE:
            if node.tagName in ('w:t', 'w:delText'):
                parts.append(node.firstChild.data if node.firstChild else '')
    return ''.join(parts)

for i, p in enumerate(body.getElementsByTagName('w:p')):
    style = ''
    for pPr in p.getElementsByTagName('w:pPr'):
        for ps in pPr.getElementsByTagName('w:pStyle'):
            style = ps.getAttribute('w:val')
    txt = para_text(p)
    if txt.strip() or style:
        print(f"[{i}] style={style!r} text={txt!r}")

